from __future__ import annotations
import discord from discord import app_commands from discord.ext import commands
from ..embeds import error_embed, info_embed, success_embed, warning_embed from ..services.guards import require_notification_target from ..ui.pagination import PagedEmbedView from ..utils import chunked, parse_channel_identifier
class ChannelCog(commands.GroupCog, name="channel"): def __init__(self, bot): self.bot = bot
async def _load_title(self, channel_id: str) -> str: return channel_id
async def _should_keep_channel(self, record) -> bool: return bool(record and (record.blacklisted or record.trackers))
@app_commands.command(name="add", description="Track a channel manually") @app_commands.describe(channel="Channel link, handle, or raw ID") async def add(self, interaction: discord.Interaction, channel: str) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) channel_id = parse_channel_identifier(channel) current = self.bot.db.get_channel(interaction.user.id, channel_id) title = current.title if current else await self._load_title(channel_id) if current and "user" in current.trackers: await interaction.response.send_message(embed=error_embed("Already pinned", "That channel is already pinned by you."), ephemeral=True) return if current: self.bot.db.add_channel_tracker(interaction.user.id, channel_id, title, "user") await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Channel pinned", f"`{channel_id}` is now pinned and will stay tracked."), ephemeral=True) return self.bot.db.upsert_channel(interaction.user.id, channel_id, title, trackers=["user"]) await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Channel added", f"`{channel_id}` was successfully added."), ephemeral=True)
@app_commands.command(name="remove", description="Remove a tracked channel or unpin it") @app_commands.describe(channel="Channel link, handle, or raw ID") async def remove(self, interaction: discord.Interaction, channel: str) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) channel_id = parse_channel_identifier(channel) current = self.bot.db.get_channel(interaction.user.id, channel_id) if not current: await interaction.response.send_message(embed=warning_embed("Channel missing", "That channel is not tracked by you."), ephemeral=True) return if current.blacklisted and "user" not in current.trackers: await interaction.response.send_message(embed=warning_embed("Blacklisted channel", "This channel is blacklisted, so it stays in the database."), ephemeral=True) return if "user" in current.trackers: removed = self.bot.db.remove_channel_tracker(interaction.user.id, channel_id, "user") await self.bot.workers.restart_user(interaction.user.id) if removed is None: await interaction.response.send_message(embed=success_embed("Channel removed", f"`{channel_id}` was removed."), ephemeral=True) else: await interaction.response.send_message(embed=success_embed("Channel unpinned", f"`{channel_id}` is no longer pinned by you."), ephemeral=True) return self.bot.db.remove_channel(interaction.user.id, channel_id) await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Channel removed", f"`{channel_id}` was removed."), ephemeral=True)
@app_commands.command(name="blacklist", description="Blacklist a channel without deleting it") @app_commands.describe(channel="Channel link, handle, or raw ID") async def blacklist(self, interaction: discord.Interaction, channel: str) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) channel_id = parse_channel_identifier(channel) current = self.bot.db.get_channel(interaction.user.id, channel_id) title = current.title if current else await self._load_title(channel_id) self.bot.db.set_channel_blacklisted(interaction.user.id, channel_id, title, True) await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Channel blacklisted", f"`{channel_id}` will be excluded from scraping."), ephemeral=True)
@app_commands.command(name="list", description="List tracked channels") @app_commands.describe(filter="Filter for list output") @app_commands.choices( filter=[ app_commands.Choice(name="all", value="all"), app_commands.Choice(name="blacklisted", value="blacklisted"), app_commands.Choice(name="playlist", value="playlist"), app_commands.Choice(name="manual", value="manual"), ] ) async def list(self, interaction: discord.Interaction, filter: app_commands.Choice[str] | None = None) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) channels = self.bot.db.list_channels_filtered(interaction.user.id, filter.value if filter else "all") if not channels: await interaction.response.send_message(embed=warning_embed("No channels found", "There are no channels matching that filter."), ephemeral=True) return rows = [] for record in channels: tracker_text = ", ".join(record.trackers) if record.trackers else "none" flags = [] if record.blacklisted: flags.append("blacklisted") if record.has_manual_tracker: flags.append("manual") if record.tracked_by_playlist: flags.append("playlist") rows.append(f"`{record.channel_id}` • {record.title} • trackers: {tracker_text} • {'/'.join(flags) or 'untracked'}") pages = [info_embed(f"Tracked channels ({index}/{(len(rows) - 1) // 8 + 1})", "\n".join(page)) for index, page in enumerate(chunked(rows, 8), start=1)] await interaction.response.send_message(embed=pages[0], view=PagedEmbedView(interaction.user.id, pages), ephemeral=True)
async def setup(bot): await bot.add_cog(ChannelCog(bot))

from __future__ import annotations
import discord from discord import app_commands from discord.ext import commands
from ..embeds import error_embed, info_embed, success_embed, warning_embed from ..services.guards import require_notification_target from ..ui.pagination import PagedEmbedView from ..utils import chunked, parse_playlist_identifier
class PlaylistCog(commands.GroupCog, name="playlist"): def __init__(self, bot): self.bot = bot
async def _playlist_title(self, playlist_id: str) -> str: return playlist_id
@app_commands.command(name="add", description="Track a playlist") @app_commands.describe(playlist="Playlist link or raw ID") async def add(self, interaction: discord.Interaction, playlist: str) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) playlist_id = parse_playlist_identifier(playlist) if playlist_id in {"LL", "LM"}: await interaction.response.send_message(embed=warning_embed("Private playlist", "Please run `/auth` first, then try again."), ephemeral=True) return title = await self._playlist_title(playlist_id) self.bot.db.upsert_playlist(interaction.user.id, playlist_id, title) await self.bot.sync_user_playlists(interaction.user.id) await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Playlist added", f"`{playlist_id}` is now being tracked."), ephemeral=True)
@app_commands.command(name="remove", description="Stop tracking a playlist") @app_commands.describe(playlist="Playlist link or raw ID") async def remove(self, interaction: discord.Interaction, playlist: str) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) playlist_id = parse_playlist_identifier(playlist) current = self.bot.db.get_playlist(interaction.user.id, playlist_id) if not current: await interaction.response.send_message(embed=warning_embed("Playlist missing", "That playlist is not tracked by you."), ephemeral=True) return self.bot.db.remove_playlist(interaction.user.id, playlist_id) await self.bot.workers.restart_user(interaction.user.id) await interaction.response.send_message(embed=success_embed("Playlist removed", f"`{playlist_id}` was removed and related channels were cleaned up."), ephemeral=True)
@app_commands.command(name="list", description="List tracked playlists") async def list(self, interaction: discord.Interaction) -> None: if not await require_notification_target(interaction, self.bot): return self.bot.db.ensure_user(interaction.user.id, interaction.guild_id) playlists = self.bot.db.list_playlists(interaction.user.id) if not playlists: await interaction.response.send_message(embed=warning_embed("No playlists found", "You have not registered any playlists yet."), ephemeral=True) return rows = [f"`{playlist.playlist_id}` • {playlist.title}" for playlist in playlists] pages = [info_embed(f"Tracked playlists ({index}/{(len(rows) - 1) // 8 + 1})", "\n".join(page)) for index, page in enumerate(chunked(rows, 8), start=1)] await interaction.response.send_message(embed=pages[0], view=PagedEmbedView(interaction.user.id, pages), ephemeral=True)
async def setup(bot): await bot.add_cog(PlaylistCog(bot))

from __future__ import annotations

import discord
from discord import app_commands
from discord.ext import commands

from ..embeds import error_embed, success_embed
from ..services.guards import require_notification_target


class WhitelistCog(commands.GroupCog, name="whitelist"):
    def __init__(self, bot):
        self.bot = bot

    def _is_owner(self, interaction: discord.Interaction) -> bool:
        return str(interaction.user.id) == str(self.bot.config.owner)

    @app_commands.command(name="add", description="Whitelist a user")
    async def add(self, interaction: discord.Interaction, user: discord.User) -> None:
        if not await require_notification_target(interaction, self.bot):
            return
        if not self.bot.config.whitelist:
            await interaction.response.send_message(embed=error_embed("Whitelist disabled", "This bot was configured without the whitelist feature."), ephemeral=True)
            return
        if not self._is_owner(interaction):
            await interaction.response.send_message(embed=error_embed("Not allowed", "Only the configured owner can use this command."), ephemeral=True)
            return
        self.bot.db.set_whitelisted(user.id, True)
        await interaction.response.send_message(embed=success_embed("Whitelist updated", f"{user.mention} is now allowed."), ephemeral=True)

    @app_commands.command(name="remove", description="Remove a user from the whitelist")
    async def remove(self, interaction: discord.Interaction, user: discord.User) -> None:
        if not await require_notification_target(interaction, self.bot):
            return
        if not self.bot.config.whitelist:
            await interaction.response.send_message(embed=error_embed("Whitelist disabled", "This bot was configured without the whitelist feature."), ephemeral=True)
            return
        if not self._is_owner(interaction):
            await interaction.response.send_message(embed=error_embed("Not allowed", "Only the configured owner can use this command."), ephemeral=True)
            return
        self.bot.db.set_whitelisted(user.id, False)
        await interaction.response.send_message(embed=success_embed("Whitelist updated", f"{user.mention} was removed from the whitelist."), ephemeral=True)


async def setup(bot):
    await bot.add_cog(WhitelistCog(bot))

from __future__ import annotations
import json from dataclasses import dataclass, field from pathlib import Path from typing import Any
@dataclass(slots=True) class BotConfig: bot_token: str = "" client_secrets_file: str = "credentials.json" token_file: str = "token.json" db_path: str = "youtify.sqlite3" listen_address: str | None = None public_base_url: str | None = None owner: str | None = None whitelist: bool = True concurrency_limit: int = 8 scrape_playlists_interval: int = 3600 check_rss_interval: int = 900 web_presence_interval: int = 300 catchup_default: bool = False youtube_api_base: str = "https://www.googleapis.com/youtube/v3" auth_success_message: str = "Authentication succeeded. You can close this page now." auth_failure_message: str = "Authentication failed. Please try again." extra: dict[str, Any] = field(default_factory=dict)
@classmethod def load(cls, path: str | Path = "config.json") -> "BotConfig": config_path = Path(path) data: dict[str, Any] = {} if config_path.exists(): data = json.loads(config_path.read_text(encoding="utf-8")) known_fields = {field.name for field in cls.__dataclass_fields__.values()} # type: ignore[attr-defined] kwargs = {k: v for k, v in data.items() if k in known_fields} extra = {k: v for k, v in data.items() if k not in known_fields} cfg = cls(**kwargs) cfg.extra = extra return cfg
def dump_template(self, path: str | Path = "config.example.json") -> None: sample = { "bot_token": "YOUR_DISCORD_BOT_TOKEN", "client_secrets_file": self.client_secrets_file, "token_file": self.token_file, "db_path": self.db_path, "listen_address": "127.0.0.1:8080", "public_base_url": "https://your-public-url.example/auth/callback", "owner": "123456789012345678", "whitelist": True, "concurrency_limit": self.concurrency_limit, "scrape_playlists_interval": self.scrape_playlists_interval, "check_rss_interval": self.check_rss_interval, "web_presence_interval": self.web_presence_interval, "catchup_default": self.catchup_default, } Path(path).write_text(json.dumps(sample, indent=2), encoding="utf-8")

from __future__ import annotations
from discord import Colour
class Palette: PRIMARY = Colour.from_rgb(88, 101, 242) SUCCESS = Colour.from_rgb(87, 242, 135) WARNING = Colour.from_rgb(250, 166, 26) ERROR = Colour.from_rgb(237, 66, 69) INFO = Colour.from_rgb(64, 156, 255) MUTED = Colour.from_rgb(113, 122, 138)

from __future__ import annotations

from discord import Embed

from .constants import Palette


def make_embed(title: str, description: str | None = None, *, color=Palette.PRIMARY) -> Embed:
    return Embed(title=title, description=description, color=color)


def success_embed(title: str, description: str | None = None) -> Embed:
    return make_embed(title, description, color=Palette.SUCCESS)


def warning_embed(title: str, description: str | None = None) -> Embed:
    return make_embed(title, description, color=Palette.WARNING)


def error_embed(title: str, description: str | None = None) -> Embed:
    return make_embed(title, description, color=Palette.ERROR)


def info_embed(title: str, description: str | None = None) -> Embed:
    return make_embed(title, description, color=Palette.INFO)

from __future__ import annotations
from dataclasses import dataclass, field from datetime import datetime from typing import Optional
@dataclass(slots=True) class UserSettings: user_id: int guild_id: Optional[int] = None notify_channel_id: Optional[int] = None notify_dms: bool = False catchup_enabled: bool = False created_at: Optional[str] = None updated_at: Optional[str] = None
@dataclass(slots=True) class ChannelRecord: user_id: int channel_id: str title: str blacklisted: bool = False last_seen_ts: Optional[str] = None trackers: list[str] = field(default_factory=list) created_at: Optional[str] = None updated_at: Optional[str] = None
@property def has_manual_tracker(self) -> bool: return "user" in self.trackers
@property def playlist_trackers(self) -> list[str]: return [tracker for tracker in self.trackers if tracker != "user"]
@property def tracked_by_playlist(self) -> bool: return any(tracker != "user" for tracker in self.trackers)
@dataclass(slots=True) class PlaylistRecord: user_id: int playlist_id: str title: str is_private: bool = False last_seen_ts: Optional[str] = None last_synced_ts: Optional[str] = None created_at: Optional[str] = None updated_at: Optional[str] = None
@dataclass(slots=True) class AuthRecord: user_id: int credential_json: str email: Optional[str] = None created_at: Optional[str] = None updated_at: Optional[str] = None
@dataclass(slots=True) class VideoRecord: video_id: str title: str url: str channel_id: str channel_title: str published_at: str thumbnail_url: Optional[str] = None
@dataclass(slots=True) class StatsSnapshot: users: int channels: int playlists: int manual_channels: int playlist_channels: int blacklisted_channels: int avg_channels_per_user: float avg_playlists_per_user: float pinned_channels: int dm_notifications: int
@dataclass(slots=True) class AuthSessionInfo: user_id: int state: str redirect_uri: str authorization_url: str created_at: datetime

from __future__ import annotations
import json import sqlite3 from contextlib import contextmanager from datetime import datetime, timezone from pathlib import Path from typing import Iterator, Sequence
from .models import AuthRecord, ChannelRecord, PlaylistRecord, StatsSnapshot, UserSettings
UTC = timezone.utc
def utc_now() -> str: return datetime.now(tz=UTC).isoformat()
class Database: def __init__(self, path: str | Path): self.path = str(path) self._connection = sqlite3.connect(self.path, check_same_thread=False) self._connection.row_factory = sqlite3.Row self.initialize()
@property def connection(self) -> sqlite3.Connection: return self._connection
def close(self) -> None: self._connection.close()
@contextmanager def cursor(self) -> Iterator[sqlite3.Cursor]: cursor = self._connection.cursor() try: yield cursor self._connection.commit() except Exception: self._connection.rollback() raise finally: cursor.close()
def initialize(self) -> None: with self.cursor() as cursor: cursor.execute( """ CREATE TABLE IF NOT EXISTS users ( user_id INTEGER PRIMARY KEY, guild_id INTEGER, notify_channel_id INTEGER, notify_dms INTEGER NOT NULL DEFAULT 0, catchup_enabled INTEGER NOT NULL DEFAULT 0, is_whitelisted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL ) """ ) cursor.execute( """ CREATE TABLE IF NOT EXISTS channels ( user_id INTEGER NOT NULL, channel_id TEXT NOT NULL, title TEXT NOT NULL, blacklisted INTEGER NOT NULL DEFAULT 0, last_seen_ts TEXT, trackers_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, channel_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ) """ ) cursor.execute( """ CREATE TABLE IF NOT EXISTS playlists ( user_id INTEGER NOT NULL, playlist_id TEXT NOT NULL, title TEXT NOT NULL, is_private INTEGER NOT NULL DEFAULT 0, last_seen_ts TEXT, last_synced_ts TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, playlist_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ) """ ) cursor.execute( """ CREATE TABLE IF NOT EXISTS auth_records ( user_id INTEGER PRIMARY KEY, credential_json TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ) """ ) cursor.execute( """ CREATE TABLE IF NOT EXISTS auth_sessions ( state TEXT PRIMARY KEY, user_id INTEGER NOT NULL, redirect_uri TEXT NOT NULL, authorization_url TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ) """ ) cursor.execute( "CREATE INDEX IF NOT EXISTS idx_channels_user ON channels(user_id)" ) cursor.execute( "CREATE INDEX IF NOT EXISTS idx_playlists_user ON playlists(user_id)" ) cursor.execute( "CREATE INDEX IF NOT EXISTS idx_channels_blacklisted ON channels(user_id, blacklisted)" )
def ensure_user(self, user_id: int, guild_id: int | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute("SELECT user_id FROM users WHERE user_id=?", (user_id,)) exists = cursor.fetchone() is not None if exists: cursor.execute( """ UPDATE users SET guild_id = COALESCE(?, guild_id), updated_at=? WHERE user_id=? """, (guild_id, now, user_id), ) else: cursor.execute( """ INSERT INTO users (user_id, guild_id, notify_channel_id, notify_dms, catchup_enabled, is_whitelisted, created_at, updated_at) VALUES (?, ?, NULL, 0, 0, 0, ?, ?) """, (user_id, guild_id, now, now), )
def upsert_user_settings(self, settings: UserSettings) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO users (user_id, guild_id, notify_channel_id, notify_dms, catchup_enabled, is_whitelisted, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, COALESCE(?, ?), ?) ON CONFLICT(user_id) DO UPDATE SET guild_id=excluded.guild_id, notify_channel_id=excluded.notify_channel_id, notify_dms=excluded.notify_dms, catchup_enabled=excluded.catchup_enabled, is_whitelisted=excluded.is_whitelisted, updated_at=excluded.updated_at """, ( settings.user_id, settings.guild_id, settings.notify_channel_id, int(settings.notify_dms), int(settings.catchup_enabled), 0, settings.created_at, now, now, ), )
def get_user_settings(self, user_id: int) -> UserSettings | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), created_at=row["created_at"], updated_at=row["updated_at"], )
def set_notify_target(self, user_id: int, guild_id: int | None, channel_id: int | None, dms: bool) -> None: self.ensure_user(user_id, guild_id) now = utc_now() with self.cursor() as cursor: cursor.execute( """ UPDATE users SET guild_id=?, notify_channel_id=?, notify_dms=?, updated_at=? WHERE user_id=? """, (guild_id, channel_id, int(dms), now, user_id), )
def set_catchup(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET catchup_enabled=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def set_whitelisted(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET is_whitelisted=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def is_whitelisted(self, user_id: int) -> bool: with self.cursor() as cursor: cursor.execute("SELECT is_whitelisted FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() return bool(row[0]) if row else False
def delete_user_everything(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM channels WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM playlists WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM auth_sessions WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM users WHERE user_id=?", (user_id,))
def get_channel(self, user_id: int, channel_id: str) -> ChannelRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id)) row = cursor.fetchone() return self._row_to_channel(user_id, row) if row else None
def list_channels(self, user_id: int, *, blacklisted: bool | None = None) -> list[ChannelRecord]: query = "SELECT * FROM channels WHERE user_id=?" params: list[object] = [user_id] if blacklisted is not None: query += " AND blacklisted=?" params.append(int(blacklisted)) query += " ORDER BY title COLLATE NOCASE, channel_id" with self.cursor() as cursor: cursor.execute(query, params) rows = cursor.fetchall() return [self._row_to_channel(user_id, row) for row in rows]
def list_channels_filtered(self, user_id: int, filter_name: str = "all") -> list[ChannelRecord]: channels = self.list_channels(user_id) match filter_name: case "blacklisted": return [channel for channel in channels if channel.blacklisted] case "playlist": return [channel for channel in channels if channel.tracked_by_playlist and not channel.blacklisted] case "manual": return [channel for channel in channels if channel.has_manual_tracker and not channel.blacklisted] case _: return channels
def count_channels(self, user_id: int | None = None) -> int: query = "SELECT COUNT(*) FROM channels" params: tuple[object, ...] = () if user_id is not None: query += " WHERE user_id=?" params = (user_id,) with self.cursor() as cursor: cursor.execute(query, params) row = cursor.fetchone() return int(row[0] if row else 0)
def upsert_channel( self, user_id: int, channel_id: str, title: str, *, blacklisted: bool | None = None, last_seen_ts: str | None = None, trackers: Sequence[str] | None = None, ) -> ChannelRecord: now = utc_now() existing = self.get_channel(user_id, channel_id) current_trackers = list(existing.trackers if existing else []) if trackers is not None: current_trackers = list(dict.fromkeys([tracker for tracker in trackers if tracker])) resolved_blacklisted = existing.blacklisted if existing and blacklisted is None else bool(blacklisted) if blacklisted is not None else False resolved_last_seen = last_seen_ts if last_seen_ts is not None else (existing.last_seen_ts if existing else None) with self.cursor() as cursor: cursor.execute( """ INSERT INTO channels (user_id, channel_id, title, blacklisted, last_seen_ts, trackers_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, COALESCE(?, ?), ?) ON CONFLICT(user_id, channel_id) DO UPDATE SET title=excluded.title, blacklisted=excluded.blacklisted, last_seen_ts=COALESCE(excluded.last_seen_ts, channels.last_seen_ts), trackers_json=excluded.trackers_json, updated_at=excluded.updated_at """, ( user_id, channel_id, title, int(resolved_blacklisted), resolved_last_seen, json.dumps(current_trackers), existing.created_at if existing else now, now, now, ), ) return self.get_channel(user_id, channel_id) or ChannelRecord(user_id=user_id, channel_id=channel_id, title=title)
def mutate_channel_trackers(self, user_id: int, channel_id: str, trackers: Sequence[str]) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET trackers_json=?, updated_at=? WHERE user_id=? AND channel_id=?", (json.dumps(list(dict.fromkeys(trackers))), now, user_id, channel_id), )
def set_channel_blacklisted(self, user_id: int, channel_id: str, title: str, blacklisted: bool) -> ChannelRecord: record = self.upsert_channel(user_id, channel_id, title, blacklisted=blacklisted) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET blacklisted=?, updated_at=? WHERE user_id=? AND channel_id=?", (int(blacklisted), now, user_id, channel_id), ) return self.get_channel(user_id, channel_id) or record
def remove_channel(self, user_id: int, channel_id: str) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id))
def add_channel_tracker(self, user_id: int, channel_id: str, title: str, tracker: str) -> ChannelRecord: current = self.get_channel(user_id, channel_id) trackers = list(current.trackers if current else []) if tracker not in trackers: trackers.append(tracker) return self.upsert_channel(user_id, channel_id, title, trackers=trackers, blacklisted=current.blacklisted if current else None, last_seen_ts=current.last_seen_ts if current else None)
def remove_channel_tracker(self, user_id: int, channel_id: str, tracker: str) -> ChannelRecord | None: current = self.get_channel(user_id, channel_id) if current is None: return None trackers = [item for item in current.trackers if item != tracker] if trackers or current.blacklisted: self.mutate_channel_trackers(user_id, channel_id, trackers) return self.get_channel(user_id, channel_id) self.remove_channel(user_id, channel_id) return None
def remove_playlist_tracker_from_channels(self, user_id: int, playlist_id: str) -> list[str]: affected: list[str] = [] for channel in self.list_channels(user_id): if playlist_id not in channel.trackers: continue affected.append(channel.channel_id) trackers = [tracker for tracker in channel.trackers if tracker != playlist_id] if trackers or channel.blacklisted: self.mutate_channel_trackers(user_id, channel.channel_id, trackers) else: self.remove_channel(user_id, channel.channel_id) return affected
def replace_playlist_channels(self, user_id: int, playlist_id: str, channel_updates: dict[str, str]) -> None: existing_channels = {row["channel_id"]: self._row_to_channel(user_id, row) for row in self._fetch_channels_for_playlist(user_id, playlist_id)} now = utc_now() with self.cursor() as cursor: for channel_id, title in channel_updates.items(): current = self.get_channel(user_id, channel_id) trackers = list(current.trackers if current else []) if playlist_id not in trackers: trackers.append(playlist_id) cursor.execute( """ INSERT INTO channels (user_id, channel_id, title, blacklisted, last_seen_ts, trackers_json, created_at, updated_at) VALUES (?, ?, ?, COALESCE(?, 0), ?, ?, COALESCE(?, ?), ?) ON CONFLICT(user_id, channel_id) DO UPDATE SET title=excluded.title, trackers_json=excluded.trackers_json, updated_at=excluded.updated_at """, ( user_id, channel_id, title, None, None, json.dumps(list(dict.fromkeys(trackers))), current.created_at if current else now, now, now, ), ) for channel_id, current in existing_channels.items(): if channel_id not in channel_updates and current: trackers = [tracker for tracker in current.trackers if tracker != playlist_id] if trackers or current.blacklisted: self.mutate_channel_trackers(user_id, channel_id, trackers) else: self.remove_channel(user_id, channel_id)
def _fetch_channels_for_playlist(self, user_id: int, playlist_id: str) -> list[sqlite3.Row]: with self.cursor() as cursor: cursor.execute( "SELECT * FROM channels WHERE user_id=? AND trackers_json LIKE ?", (user_id, f'%"{playlist_id}"%'), ) return cursor.fetchall()
def _row_to_channel(self, user_id: int, row: sqlite3.Row) -> ChannelRecord: trackers = json.loads(row["trackers_json"] or "[]") return ChannelRecord( user_id=user_id, channel_id=row["channel_id"], title=row["title"], blacklisted=bool(row["blacklisted"]), last_seen_ts=row["last_seen_ts"], trackers=list(trackers), created_at=row["created_at"], updated_at=row["updated_at"], )
def upsert_playlist(self, user_id: int, playlist_id: str, title: str, *, is_private: bool = False) -> PlaylistRecord: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO playlists (user_id, playlist_id, title, is_private, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, playlist_id) DO UPDATE SET title=excluded.title, is_private=excluded.is_private, updated_at=excluded.updated_at """, (user_id, playlist_id, title, int(is_private), now, now), ) return self.get_playlist(user_id, playlist_id) or PlaylistRecord(user_id=user_id, playlist_id=playlist_id, title=title)
def get_playlist(self, user_id: int, playlist_id: str) -> PlaylistRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM playlists WHERE user_id=? AND playlist_id=?", (user_id, playlist_id)) row = cursor.fetchone() if row is None: return None return PlaylistRecord( user_id=row["user_id"], playlist_id=row["playlist_id"], title=row["title"], is_private=bool(row["is_private"]), last_seen_ts=row["last_seen_ts"], last_synced_ts=row["last_synced_ts"], created_at=row["created_at"], updated_at=row["updated_at"], )
def list_playlists(self, user_id: int) -> list[PlaylistRecord]: with self.cursor() as cursor: cursor.execute( "SELECT * FROM playlists WHERE user_id=? ORDER BY title COLLATE NOCASE, playlist_id", (user_id,), ) rows = cursor.fetchall() return [self.get_playlist(user_id, row["playlist_id"]) for row in rows if row]
def remove_playlist(self, user_id: int, playlist_id: str) -> None: current = self.get_playlist(user_id, playlist_id) with self.cursor() as cursor: cursor.execute("DELETE FROM playlists WHERE user_id=? AND playlist_id=?", (user_id, playlist_id)) if current is None: return channels = self.list_channels(user_id) for channel in channels: if playlist_id not in channel.trackers: continue trackers = [tracker for tracker in channel.trackers if tracker != playlist_id] if trackers or channel.blacklisted: self.mutate_channel_trackers(user_id, channel.channel_id, trackers) else: self.remove_channel(user_id, channel.channel_id)
def set_playlist_seen(self, user_id: int, playlist_id: str, ts: str | None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE playlists SET last_seen_ts=?, updated_at=? WHERE user_id=? AND playlist_id=?", (ts, now, user_id, playlist_id), )
def set_playlist_synced(self, user_id: int, playlist_id: str, ts: str | None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE playlists SET last_synced_ts=?, updated_at=? WHERE user_id=? AND playlist_id=?", (ts, now, user_id, playlist_id), )
def list_users(self) -> list[UserSettings]: with self.cursor() as cursor: cursor.execute("SELECT * FROM users ORDER BY user_id") rows = cursor.fetchall() return [ UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), created_at=row["created_at"], updated_at=row["updated_at"], ) for row in rows ]
def count_users(self) -> int: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") row = cursor.fetchone() return int(row[0] if row else 0)
def set_auth_record(self, user_id: int, credential_json: str, email: str | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO auth_records (user_id, credential_json, email, created_at, updated_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET credential_json=excluded.credential_json, email=excluded.email, updated_at=excluded.updated_at """, (user_id, credential_json, email, now, now), )
def get_auth_record(self, user_id: int) -> AuthRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM auth_records WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return AuthRecord( user_id=row["user_id"], credential_json=row["credential_json"], email=row["email"], created_at=row["created_at"], updated_at=row["updated_at"], )
def remove_auth_record(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,))
def create_auth_session(self, user_id: int, state: str, redirect_uri: str, authorization_url: str, expires_at: str) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT OR REPLACE INTO auth_sessions (state, user_id, redirect_uri, authorization_url, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?) """, (state, user_id, redirect_uri, authorization_url, now, expires_at), )
def get_auth_session(self, state: str) -> sqlite3.Row | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM auth_sessions WHERE state=?", (state,)) return cursor.fetchone()
def delete_auth_session(self, state: str) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM auth_sessions WHERE state=?", (state,))
def cleanup_auth_sessions(self) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute("DELETE FROM auth_sessions WHERE expires_at < ?", (now,))
def stats_snapshot(self) -> StatsSnapshot: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") users = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels") channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists") playlists = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE blacklisted=1") blacklisted = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE trackers_json LIKE '%\"user\"%'") pinned = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM users WHERE notify_dms=1") dms = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE trackers_json LIKE '%\"user\"%' AND blacklisted=0") manual_channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE trackers_json NOT LIKE '%\"user\"%' AND blacklisted=0") playlist_channels = int(cursor.fetchone()[0]) avg_channels = channels / users if users else 0.0 avg_playlists = playlists / users if users else 0.0 return StatsSnapshot( users=users, channels=channels, playlists=playlists, manual_channels=manual_channels, playlist_channels=playlist_channels, blacklisted_channels=blacklisted, avg_channels_per_user=avg_channels, avg_playlists_per_user=avg_playlists, pinned_channels=pinned, dm_notifications=dms, )
def count_user_objects(self, user_id: int) -> tuple[int, int]: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM channels WHERE user_id=?", (user_id,)) channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists WHERE user_id=?", (user_id,)) playlists = int(cursor.fetchone()[0]) return channels, playlists

from __future__ import annotations

import asyncio
import contextlib
from dataclasses import dataclass
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from ..bot import YoutifyBot


@dataclass(slots=True)
class UserWorkerState:
    task: asyncio.Task | None = None
    stop_event: asyncio.Event | None = None


class UserTaskManager:
    def __init__(self, bot: YoutifyBot):
        self.bot = bot
        self._workers: dict[int, UserWorkerState] = {}

    def has_worker(self, user_id: int) -> bool:
        worker = self._workers.get(user_id)
        return bool(worker and worker.task and not worker.task.done())

    async def stop_user(self, user_id: int) -> None:
        worker = self._workers.get(user_id)
        if not worker:
            return
        if worker.stop_event:
            worker.stop_event.set()
        if worker.task:
            worker.task.cancel()
            with contextlib.suppress(asyncio.CancelledError):
                await worker.task
        self._workers.pop(user_id, None)

    async def restart_user(self, user_id: int) -> None:
        await self.stop_user(user_id)
        await self.start_user(user_id)

    async def start_user(self, user_id: int) -> None:
        channels, playlists = self.bot.db.count_user_objects(user_id)
        if channels <= 0 and playlists <= 0:
            return
        if self.has_worker(user_id):
            return
        stop_event = asyncio.Event()
        task = asyncio.create_task(self._run_user(user_id, stop_event), name=f"youtify-user-{user_id}")
        self._workers[user_id] = UserWorkerState(task=task, stop_event=stop_event)

    async def _run_user(self, user_id: int, stop_event: asyncio.Event) -> None:
        playlist_interval = max(60, int(self.bot.config.scrape_playlists_interval))
        rss_interval = max(60, int(self.bot.config.check_rss_interval))
        while not stop_event.is_set():
            try:
                await self.bot.sync_user_playlists(user_id)
                await self.bot.process_user_rss(user_id)
            except asyncio.CancelledError:
                raise
            except Exception:
                self.bot.logger.exception("User worker failed for %s", user_id)
            wait_seconds = min(playlist_interval, rss_interval)
            try:
                await asyncio.wait_for(stop_event.wait(), timeout=wait_seconds)
            except asyncio.TimeoutError:
                continue

from __future__ import annotations
from dataclasses import dataclass
import discord from discord import ui
from ..embeds import info_embed, warning_embed
@dataclass(slots=True) class PageViewState: pages: list[discord.Embed] index: int = 0
class PagedEmbedView(ui.View): def __init__(self, owner_id: int, pages: list[discord.Embed], *, timeout: float = 300.0): super().__init__(timeout=timeout) self.owner_id = owner_id self.state = PageViewState(pages=pages, index=0) self._update_buttons()
def _update_buttons(self) -> None: self.first.disabled = self.state.index <= 0 self.prev.disabled = self.state.index <= 0 self.next.disabled = self.state.index >= len(self.state.pages) - 1 self.last.disabled = self.state.index >= len(self.state.pages) - 1 self.counter.label = f"{self.state.index + 1}/{len(self.state.pages)}"
async def interaction_check(self, interaction: discord.Interaction) -> bool: if interaction.user.id != self.owner_id: await interaction.response.send_message( embed=warning_embed("Not your pagination", "Only the command sender can use these buttons."), ephemeral=True, ) return False return True
async def show(self, interaction: discord.Interaction) -> None: self._update_buttons() await interaction.response.send_message(embed=self.state.pages[self.state.index], view=self)
async def _switch(self, interaction: discord.Interaction, new_index: int) -> None: self.state.index = new_index self._update_buttons() await interaction.response.edit_message(embed=self.state.pages[self.state.index], view=self)
@ui.button(label="⏮", style=discord.ButtonStyle.secondary) async def first(self, interaction: discord.Interaction, button: ui.Button) -> None: await self._switch(interaction, 0)
@ui.button(label="◀", style=discord.ButtonStyle.secondary) async def prev(self, interaction: discord.Interaction, button: ui.Button) -> None: await self._switch(interaction, max(0, self.state.index - 1))
@ui.button(label="1/1", style=discord.ButtonStyle.primary, disabled=True) async def counter(self, interaction: discord.Interaction, button: ui.Button) -> None: await interaction.response.defer()
@ui.button(label="▶", style=discord.ButtonStyle.secondary) async def next(self, interaction: discord.Interaction, button: ui.Button) -> None: await self._switch(interaction, min(len(self.state.pages) - 1, self.state.index + 1))
@ui.button(label="⏭", style=discord.ButtonStyle.secondary) async def last(self, interaction: discord.Interaction, button: ui.Button) -> None: await self._switch(interaction, len(self.state.pages) - 1)

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Iterable, Sequence
from urllib.parse import parse_qs, urlparse

CHANNEL_ID_RE = re.compile(r"^(UC[\w-]{20,}|[A-Za-z0-9_-]{24})$")
PLAYLIST_ID_RE = re.compile(r"^([A-Za-z0-9_-]{10,}|LL|LM|WL)$")
HANDLE_RE = re.compile(r"@([A-Za-z0-9._-]{2,})")


@dataclass(slots=True)
class ParsedTarget:
    raw: str
    id: str
    kind: str


def chunked(items: Sequence[str], size: int) -> list[list[str]]:
    return [list(items[i : i + size]) for i in range(0, len(items), size)]


def normalize_input(value: str) -> str:
    return value.strip()


def parse_playlist_identifier(value: str) -> str:
    value = normalize_input(value)
    parsed = urlparse(value)
    if parsed.scheme and parsed.netloc:
        query = parse_qs(parsed.query)
        if "list" in query and query["list"]:
            return query["list"][0]
        path = parsed.path.rstrip("/")
        if path:
            candidate = path.split("/")[-1]
            if candidate:
                return candidate
    return value.split("?")[0].split("&")[0]


def parse_channel_identifier(value: str) -> str:
    value = normalize_input(value)
    parsed = urlparse(value)
    if parsed.scheme and parsed.netloc:
        path = parsed.path.strip("/")
        query = parse_qs(parsed.query)
        if "channel_id" in query and query["channel_id"]:
            return query["channel_id"][0]
        if path.startswith("channel/"):
            return path.split("/")[-1]
        if path.startswith("@"):
            return path.split("/")[-1]
        if path.startswith("user/"):
            return path.split("/")[-1]
        if path.startswith("c/"):
            return path.split("/")[-1]
    if value.startswith("@"): 
        return value[1:]
    return value.split("?")[0].split("&")[0]


def looks_like_playlist(value: str) -> bool:
    candidate = parse_playlist_identifier(value)
    return bool(PLAYLIST_ID_RE.match(candidate) or candidate.startswith(("PL", "LL", "LM", "WL", "UU")))


def looks_like_channel(value: str) -> bool:
    candidate = parse_channel_identifier(value)
    return bool(CHANNEL_ID_RE.match(candidate) or candidate.startswith("UC") or value.startswith("@"))


def extract_youtube_handle(value: str) -> str | None:
    match = HANDLE_RE.search(value)
    if match:
        return match.group(1)
    parsed = urlparse(value)
    if parsed.scheme and parsed.netloc:
        path = parsed.path.strip("/")
        if path.startswith("@"): 
            return path[1:]
    if value.startswith("@"): 
        return value[1:]
    return None


def text_pages(items: Iterable[str], per_page: int = 10) -> list[str]:
    page: list[str] = []
    pages: list[str] = []
    for item in items:
        page.append(item)
        if len(page) == per_page:
            pages.append("\n".join(page))
            page = []
    if page:
        pages.append("\n".join(page))
    return pages

from __future__ import annotations
import sqlite3 from contextlib import contextmanager from datetime import timezone from pathlib import Path from typing import Iterator, Sequence
from models import AuthRecord, ChannelRecord, PlaylistRecord, StatsSnapshot, UserSettings from utils import utc_now
# noinspection PyArgumentList class Database: def __init__(self, path: str | Path): self.path = str(path) self._connection = sqlite3.connect(self.path, check_same_thread=False) self._connection.row_factory = sqlite3.Row # Enable foreign key constraints self._connection.execute("PRAGMA foreign_keys = ON") self.initialize()
@property def connection(self) -> sqlite3.Connection: return self._connection
def close(self) -> None: self._connection.close()
@contextmanager def cursor(self) -> Iterator[sqlite3.Cursor]: cursor = self._connection.cursor() try: yield cursor self._connection.commit() except Exception: self._connection.rollback() raise finally: cursor.close()
def initialize(self) -> None: with self.cursor() as cursor: cursor.executescript( """ CREATE TABLE IF NOT EXISTS users ( user_id INTEGER PRIMARY KEY, guild_id INTEGER, notify_channel_id INTEGER, notify_dms INTEGER NOT NULL DEFAULT 0, catchup_enabled INTEGER NOT NULL DEFAULT 0, is_whitelisted INTEGER NOT NULL DEFAULT 0, next_playlist_run REAL NOT NULL DEFAULT 0.0, next_latest_run REAL NOT NULL DEFAULT 0.0, priority_job TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL ); CREATE TABLE IF NOT EXISTS channels ( user_id INTEGER NOT NULL, channel_id TEXT NOT NULL, title TEXT NOT NULL, blacklisted INTEGER NOT NULL DEFAULT 0, last_seen_ts TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, channel_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS channel_trackers ( user_id INTEGER NOT NULL, channel_id TEXT NOT NULL, tracker_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (user_id, channel_id, tracker_id), FOREIGN KEY (user_id, channel_id) REFERENCES channels(user_id, channel_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_channel_trackers_user ON channel_trackers(user_id); CREATE INDEX IF NOT EXISTS idx_channel_trackers_tracker ON channel_trackers(user_id, tracker_id); CREATE TABLE IF NOT EXISTS playlists ( user_id INTEGER NOT NULL, playlist_id TEXT NOT NULL, title TEXT NOT NULL, is_private INTEGER NOT NULL DEFAULT 0, last_synced_ts TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, playlist_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS auth_records ( user_id INTEGER PRIMARY KEY, credential_json TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_channels_user ON channels(user_id); CREATE INDEX IF NOT EXISTS idx_playlists_user ON playlists(user_id); CREATE INDEX IF NOT EXISTS idx_channels_blacklisted ON channels(user_id, blacklisted); """ )
# Migration: add worker scheduling columns if they don't exist with self.cursor() as cursor: try: cursor.execute("SELECT next_playlist_run FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN next_playlist_run REAL NOT NULL DEFAULT 0.0") try: cursor.execute("SELECT next_latest_run FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN next_latest_run REAL NOT NULL DEFAULT 0.0") try: cursor.execute("SELECT priority_job FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN priority_job TEXT")
def ensure_user(self, user_id: int, guild_id: int | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute("SELECT user_id FROM users WHERE user_id=?", (user_id,)) exists = cursor.fetchone() is not None if exists: cursor.execute( """ UPDATE users SET guild_id = COALESCE(?, guild_id), updated_at=? WHERE user_id=? """, (guild_id, now, user_id), ) else: cursor.execute( """ INSERT INTO users (user_id, guild_id, notify_channel_id, notify_dms, catchup_enabled, is_whitelisted, created_at, updated_at) VALUES (?, ?, NULL, 0, 0, 0, ?, ?) """, (user_id, guild_id, now, now), )
def get_user_settings(self, user_id: int) -> UserSettings | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), next_playlist_run=float(row["next_playlist_run"]) if row["next_playlist_run"] else 0.0, next_latest_run=float(row["next_latest_run"]) if row["next_latest_run"] else 0.0, priority_job=row["priority_job"], created_at=row["created_at"], updated_at=row["updated_at"], )
def set_notify_target(self, user_id: int, guild_id: int | None, channel_id: int | None, dms: bool) -> None: self.ensure_user(user_id, guild_id) now = utc_now() with self.cursor() as cursor: cursor.execute( """ UPDATE users SET guild_id=?, notify_channel_id=?, notify_dms=?, updated_at=? WHERE user_id=? """, (guild_id, channel_id, int(dms), now, user_id), )
def set_catchup(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET catchup_enabled=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def set_whitelisted(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET is_whitelisted=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def is_whitelisted(self, user_id: int) -> bool: with self.cursor() as cursor: cursor.execute("SELECT is_whitelisted FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() return bool(row[0]) if row else False
def list_whitelisted_users(self) -> list[int]: with self.cursor() as cursor: cursor.execute("SELECT user_id FROM users WHERE is_whitelisted=1 ORDER BY user_id") rows = cursor.fetchall() return [row[0] for row in rows]
def set_worker_schedule(self, user_id: int, *, next_playlist_run: float | None = None, next_latest_run: float | None = None, priority_job: str | None = None) -> None: """Update worker scheduling state. Only updates provided fields.""" self.ensure_user(user_id) now = utc_now()
updates = [] params = []
if next_playlist_run is not None: updates.append("next_playlist_run=?") params.append(next_playlist_run) if next_latest_run is not None: updates.append("next_latest_run=?") params.append(next_latest_run) if priority_job is not None: updates.append("priority_job=?") params.append(priority_job)
if updates: updates.append("updated_at=?") params.append(now) params.append(user_id)
query = f"UPDATE users SET {', '.join(updates)} WHERE user_id=?" with self.cursor() as cursor: cursor.execute(query, params)
def get_worker_schedule(self, user_id: int) -> tuple[float, float, str | None]: """Get worker scheduling state. Returns (next_playlist_run, next_latest_run, priority_job).""" with self.cursor() as cursor: cursor.execute("SELECT next_playlist_run, next_latest_run, priority_job FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone()
if row is None: return 0.0, 0.0, None
return ( float(row["next_playlist_run"]) if row["next_playlist_run"] else 0.0, float(row["next_latest_run"]) if row["next_latest_run"] else 0.0, row["priority_job"] )
def delete_user(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM users WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM channels WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM playlists WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,))
def get_channel(self, user_id: int, channel_id: str) -> ChannelRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id)) row = cursor.fetchone() return self._row_to_channel(user_id, row) if row else None
def count_channels(self, user_id: int | None = None, filter_name: str | None = "all") -> int: query = "SELECT COUNT(*) FROM channels c" conditions: list[str] = [] params: list[object] = []
if user_id is not None: conditions.append("c.user_id=?") params.append(user_id)
match filter_name: case "blacklisted": conditions.append("c.blacklisted=1") case "manual": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
if conditions: query += " WHERE " + " AND ".join(conditions)
with self.cursor() as cursor: cursor.execute(query, params) row = cursor.fetchone()
return int(row[0] if row else 0)
def list_channels(self, user_id: int, filter_name: str = "all") -> Iterator[ChannelRecord]: query = "SELECT c.* FROM channels c" conditions: list[str] = ["c.user_id = ?"] params: list[object] = [user_id]
match filter_name: case "blacklisted": conditions.append("c.blacklisted = 1") case "manual": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
query += " WHERE " + " AND ".join(conditions) query += " ORDER BY c.title COLLATE NOCASE, c.channel_id"
with self.cursor() as cursor: cursor.execute(query, params) rows = cursor.fetchall()
for row in rows: yield self._row_to_channel(user_id, row)
def list_channels_paginated(self, user_id: int, limit: int = 5, offset: int = 0, filter_name: str = "all") -> list[ChannelRecord]: query = "SELECT c.* FROM channels c" conditions: list[str] = ["c.user_id=?"] params: list[object] = [user_id]
match filter_name: case "blacklisted": conditions.append("c.blacklisted=1") case "manual": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
query += " WHERE " + " AND ".join(conditions) query += " ORDER BY c.title COLLATE NOCASE, c.channel_id LIMIT ? OFFSET ?"
params.extend([limit, offset])
with self.cursor() as cursor: cursor.execute(query, params) rows = cursor.fetchall()
return [self._row_to_channel(user_id, row) for row in rows]
def upsert_channel( self, user_id: int, channel_id: str, title: str, *, blacklisted: bool | None = None, last_seen_ts: str | None = None, trackers: Sequence[str] | None = None, ) -> ChannelRecord: now = utc_now() existing = self.get_channel(user_id, channel_id)
resolved_blacklisted = existing.blacklisted if existing and blacklisted is None else bool(blacklisted) if blacklisted is not None else False resolved_last_seen = last_seen_ts if last_seen_ts is not None else (existing.last_seen_ts if existing else None)
with self.cursor() as cursor: cursor.execute( """ INSERT INTO channels (user_id, channel_id, title, blacklisted, last_seen_ts, created_at, updated_at) VALUES (?, ?, ?, ?, ?, COALESCE(?, ?), ?) ON CONFLICT(user_id, channel_id) DO UPDATE SET title=excluded.title, blacklisted=excluded.blacklisted, last_seen_ts=CASE WHEN excluded.last_seen_ts IS NULL THEN channels.last_seen_ts WHEN channels.last_seen_ts IS NULL THEN excluded.last_seen_ts WHEN excluded.last_seen_ts > channels.last_seen_ts THEN excluded.last_seen_ts ELSE channels.last_seen_ts END, updated_at=excluded.updated_at """, ( user_id, channel_id, title, int(resolved_blacklisted), resolved_last_seen, existing.created_at if existing else now, now, now ), )
if trackers: incoming_trackers = list(dict.fromkeys([t for t in trackers if t])) cursor.executemany( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) VALUES (?, ?, ?, ?) """, [(user_id, channel_id, tracker_id, now) for tracker_id in incoming_trackers] )
return self.get_channel(user_id, channel_id) or ChannelRecord(user_id=user_id, channel_id=channel_id, title=title)
def upsert_playlist_channels( self, user_id: int, playlist_id: str, channels: dict[str, str], last_seen: dict[str, str] | None = None ) -> None: now = utc_now() is_dict_present = last_seen is not None last_seen_dict = last_seen or {}
with self.cursor() as cursor: cursor.executemany( """ INSERT INTO channels ( user_id, channel_id, title, blacklisted, last_seen_ts, created_at, updated_at ) -- FIX: If it's a new row insert and incoming is NULL, default to :now VALUES (:user_id, :channel_id, :title, 0, COALESCE(:incoming_last_seen, :now), :now, :now) ON CONFLICT(user_id, channel_id) DO UPDATE SET title = excluded.title, created_at = CASE WHEN excluded.title != channels.title THEN max(excluded.created_at, channels.created_at) ELSE channels.created_at END,
last_seen_ts = CASE -- RULE 1: last_seen dict is null WHEN :is_dict_present = 0 THEN COALESCE(channels.last_seen_ts, excluded.updated_at)
-- RULE 2: last_seen dict is present ELSE CASE WHEN channels.last_seen_ts IS NULL OR excluded.last_seen_ts > channels.last_seen_ts THEN excluded.last_seen_ts ELSE channels.last_seen_ts END END,
updated_at = excluded.updated_at """, [ { "user_id": user_id, "channel_id": cid, "title": title, "incoming_last_seen": last_seen_dict.get(cid), "is_dict_present": 1 if is_dict_present else 0, "now": now, } for cid, title in channels.items() ], )
cursor.executemany( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) VALUES (?, ?, ?, ?) """, [(user_id, cid, playlist_id, now) for cid in channels], )
def set_channel_blacklisted(self, user_id: int, channel_id: str, title: str, blacklisted: bool) -> ChannelRecord: record = self.upsert_channel(user_id, channel_id, title, blacklisted=blacklisted) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET blacklisted=?, updated_at=? WHERE user_id=? AND channel_id=?", (int(blacklisted), now, user_id, channel_id), ) return self.get_channel(user_id, channel_id) or record
def remove_channel(self, user_id: int, channel_id: str) -> None: with self.cursor() as cursor: cursor.execute( "DELETE FROM channel_trackers WHERE user_id=? AND channel_id=?", (user_id, channel_id) ) cursor.execute( "DELETE FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id) )
def add_channel_tracker(self, user_id: int, channel_id: str, tracker: str): now = utc_now()
with self.cursor() as cursor: cursor.execute( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) SELECT ?, ?, ?, ? WHERE EXISTS ( SELECT 1 FROM channels WHERE user_id=? AND channel_id=? ) """, (user_id, channel_id, tracker, now, user_id, channel_id), )
def remove_channel_tracker(self, user_id: int, channel_id: str, tracker: str) -> bool: with self.cursor() as cursor: cursor.execute( """ DELETE FROM channel_trackers WHERE user_id=? AND channel_id=? AND tracker_id=? """, (user_id, channel_id, tracker), )
removed = cursor.rowcount > 0
if not removed: return False
cursor.execute( """ DELETE FROM channels WHERE user_id=? AND channel_id=? AND blacklisted=0 AND NOT EXISTS ( SELECT 1 FROM channel_trackers WHERE user_id=? AND channel_id=? ) """, (user_id, channel_id, user_id, channel_id), )
return True
def remove_orphaned_playlist_channels(self, user_id: int, playlist_id: str, cutoff: str) -> None: with self.cursor() as cursor: cursor.execute(""" CREATE TEMP TABLE tmp_stale AS SELECT c.channel_id FROM channels c JOIN channel_trackers ct ON ct.user_id = c.user_id AND ct.channel_id = c.channel_id WHERE c.user_id = ? AND ct.tracker_id = ? AND c.updated_at < ? """, (user_id, playlist_id, cutoff))
cursor.execute(""" DELETE FROM channel_trackers WHERE user_id = ? AND tracker_id = ? AND channel_id IN (SELECT channel_id FROM tmp_stale) """, (user_id, playlist_id))
cursor.execute(""" DELETE FROM channels WHERE user_id = ? AND channel_id IN ( SELECT s.channel_id FROM tmp_stale s LEFT JOIN channel_trackers ct ON ct.user_id = ? AND ct.channel_id = s.channel_id WHERE ct.channel_id IS NULL ) AND blacklisted = 0 """, (user_id, user_id))
cursor.execute("DROP TABLE tmp_stale")
def reset_channels_last_seen(self, user_id: int) -> int: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET last_seen_ts=NULL, updated_at=? WHERE user_id=?", (now, user_id), ) return cursor.rowcount
@staticmethod def _row_to_playlist(row: sqlite3.Row) -> PlaylistRecord: return PlaylistRecord( user_id=row["user_id"], playlist_id=row["playlist_id"], title=row["title"], is_private=bool(row["is_private"]), last_synced_ts=row["last_synced_ts"], created_at=row["created_at"], updated_at=row["updated_at"], )
def _row_to_channel(self, user_id: int, row: sqlite3.Row) -> ChannelRecord: with self.cursor() as cursor: cursor.execute( """ SELECT tracker_id FROM channel_trackers WHERE user_id=? AND channel_id=? """, (user_id, row["channel_id"]), ) trackers = [r[0] for r in cursor.fetchall()]
return ChannelRecord( user_id=user_id, channel_id=row["channel_id"], title=row["title"], blacklisted=bool(row["blacklisted"]), last_seen_ts=row["last_seen_ts"], trackers=trackers, created_at=row["created_at"], updated_at=row["updated_at"], )
def upsert_playlist(self, user_id: int, playlist_id: str, title: str, *, is_private: bool = False) -> PlaylistRecord: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO playlists (user_id, playlist_id, title, is_private, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, playlist_id) DO UPDATE SET title=excluded.title, is_private=excluded.is_private, updated_at=excluded.updated_at """, (user_id, playlist_id, title, int(is_private), now, now), ) return self.get_playlist(user_id, playlist_id)
def get_playlist(self, user_id: int, playlist_id: str) -> PlaylistRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM playlists WHERE user_id=? AND playlist_id=?", (user_id, playlist_id)) row = cursor.fetchone() if row is None: return None return self._row_to_playlist(row)
def list_playlists(self, user_id: int) -> Iterator[PlaylistRecord]: with self.cursor() as cursor: cursor.execute( """ SELECT * FROM playlists WHERE user_id=? ORDER BY title COLLATE NOCASE, playlist_id """, (user_id,), )
while True: rows = cursor.fetchmany(10) if not rows: break
for row in rows: if row: yield self._row_to_playlist(row)
def count_playlists(self, user_id: int) -> int: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM playlists WHERE user_id=?", (user_id,)) row = cursor.fetchone() return int(row[0] if row else 0)
def list_playlists_paginated(self, user_id: int, limit: int = 10, offset: int = 0) -> list[PlaylistRecord]: with self.cursor() as cursor: cursor.execute( "SELECT * FROM playlists WHERE user_id=? ORDER BY title COLLATE NOCASE, playlist_id LIMIT ? OFFSET ?", (user_id, limit, offset), ) rows = cursor.fetchall() return [self.get_playlist(user_id, row["playlist_id"]) for row in rows if row]
def set_playlist_synced(self, user_id: int, playlist_id: str, ts: str | None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE playlists SET last_synced_ts=?, updated_at=? WHERE user_id=? AND playlist_id=?", (ts, now, user_id, playlist_id), )
def remove_playlist(self, user_id: int, playlist_id: str) -> int: with self.cursor() as cursor: cursor.execute( """ DELETE FROM channel_trackers WHERE user_id = ? AND tracker_id = ? """, (user_id, playlist_id), ) removed_count = cursor.rowcount
cursor.execute( """ DELETE FROM playlists WHERE user_id = ? AND playlist_id = ? """, (user_id, playlist_id), )
cursor.execute( """ DELETE FROM channels WHERE user_id = ? AND blacklisted = 0 AND channel_id NOT IN ( SELECT channel_id FROM channel_trackers WHERE user_id = ? ) """, (user_id, user_id), )
return removed_count
def list_users(self) -> list[UserSettings]: with self.cursor() as cursor: cursor.execute("SELECT * FROM users ORDER BY user_id") rows = cursor.fetchall() return [ UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), created_at=row["created_at"], updated_at=row["updated_at"], ) for row in rows ]
def count_users(self) -> int: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") row = cursor.fetchone() return int(row[0] if row else 0)
def set_auth_record(self, user_id: int, credential_json: str, email: str | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO auth_records (user_id, credential_json, email, created_at, updated_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET credential_json=excluded.credential_json, email=excluded.email, updated_at=excluded.updated_at """, (user_id, credential_json, email, now, now), )
def get_auth_record(self, user_id: int) -> AuthRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM auth_records WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return AuthRecord( user_id=row["user_id"], credential_json=row["credential_json"], email=row["email"], created_at=row["created_at"], updated_at=row["updated_at"], )
def remove_auth_record(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,))
def stats_snapshot(self) -> StatsSnapshot: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") users = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels") channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists") playlists = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE blacklisted=1") blacklisted = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(DISTINCT channel_id) FROM channel_trackers WHERE tracker_id='user'") pinned = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM users WHERE notify_dms=1") dms = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM users WHERE notify_channel_id IS NOT NULL") channel_notifs = int(cursor.fetchone()[0]) cursor.execute(""" SELECT COUNT(*) FROM channels c WHERE c.blacklisted=0 AND EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user') """) manual_channels = int(cursor.fetchone()[0]) cursor.execute(""" SELECT COUNT(*) FROM channels c WHERE c.blacklisted=0 AND EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user') """) playlist_channels = int(cursor.fetchone()[0]) avg_channels = channels / users if users else 0.0 avg_playlists = playlists / users if users else 0.0 return StatsSnapshot( users=users, channels=channels, playlists=playlists, manual_channels=manual_channels, playlist_channels=playlist_channels, blacklisted_channels=blacklisted, avg_channels_per_user=avg_channels, avg_playlists_per_user=avg_playlists, pinned_channels=pinned, dm_notifications=dms, channel_notifications=channel_notifs )
def count_user_objects(self, user_id: int) -> tuple[int, int]: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM channels WHERE user_id=?", (user_id,)) channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists WHERE user_id=?", (user_id,)) playlists = int(cursor.fetchone()[0]) return channels, playlists

from __future__ import annotations
import sqlite3 from contextlib import contextmanager from datetime import timezone from pathlib import Path from typing import Iterator, Sequence
from models import AuthRecord, ChannelRecord, PlaylistRecord, StatsSnapshot, UserSettings from utils import utc_now
# noinspection PyArgumentList class Database: def __init__(self, path: str | Path): self.path = str(path) self._connection = sqlite3.connect(self.path, check_same_thread=False) self._connection.row_factory = sqlite3.Row # Enable foreign key constraints self._connection.execute("PRAGMA foreign_keys = ON") self.initialize()
@property def connection(self) -> sqlite3.Connection: return self._connection
def close(self) -> None: self._connection.close()
@contextmanager def cursor(self) -> Iterator[sqlite3.Cursor]: cursor = self._connection.cursor() try: yield cursor self._connection.commit() except Exception: self._connection.rollback() raise finally: cursor.close()
def initialize(self) -> None: with self.cursor() as cursor: cursor.executescript( """ CREATE TABLE IF NOT EXISTS users ( user_id INTEGER PRIMARY KEY, guild_id INTEGER, notify_channel_id INTEGER, notify_dms INTEGER NOT NULL DEFAULT 0, catchup_enabled INTEGER NOT NULL DEFAULT 0, is_whitelisted INTEGER NOT NULL DEFAULT 0, next_playlist_run REAL NOT NULL DEFAULT 0.0, next_latest_run REAL NOT NULL DEFAULT 0.0, priority_job TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL ); CREATE TABLE IF NOT EXISTS channels ( user_id INTEGER NOT NULL, channel_id TEXT NOT NULL, title TEXT NOT NULL, blacklisted INTEGER NOT NULL DEFAULT 0, last_seen_ts TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, channel_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS channel_trackers ( user_id INTEGER NOT NULL, channel_id TEXT NOT NULL, tracker_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (user_id, channel_id, tracker_id), FOREIGN KEY (user_id, channel_id) REFERENCES channels(user_id, channel_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_channel_trackers_user ON channel_trackers(user_id); CREATE INDEX IF NOT EXISTS idx_channel_trackers_tracker ON channel_trackers(user_id, tracker_id); CREATE TABLE IF NOT EXISTS playlists ( user_id INTEGER NOT NULL, playlist_id TEXT NOT NULL, title TEXT NOT NULL, is_private INTEGER NOT NULL DEFAULT 0, last_synced_ts TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, playlist_id), FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE TABLE IF NOT EXISTS auth_records ( user_id INTEGER PRIMARY KEY, credential_json TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE ); CREATE INDEX IF NOT EXISTS idx_channels_user ON channels(user_id); CREATE INDEX IF NOT EXISTS idx_playlists_user ON playlists(user_id); CREATE INDEX IF NOT EXISTS idx_channels_blacklisted ON channels(user_id, blacklisted); """ )
# Migration: add worker scheduling columns if they don't exist with self.cursor() as cursor: try: cursor.execute("SELECT next_playlist_run FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN next_playlist_run REAL NOT NULL DEFAULT 0.0") try: cursor.execute("SELECT next_latest_run FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN next_latest_run REAL NOT NULL DEFAULT 0.0") try: cursor.execute("SELECT priority_job FROM users LIMIT 1") except Exception: cursor.execute("ALTER TABLE users ADD COLUMN priority_job TEXT")
def ensure_user(self, user_id: int, guild_id: int | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute("SELECT user_id FROM users WHERE user_id=?", (user_id,)) exists = cursor.fetchone() is not None if exists: cursor.execute( """ UPDATE users SET guild_id = COALESCE(?, guild_id), updated_at=? WHERE user_id=? """, (guild_id, now, user_id), ) else: cursor.execute( """ INSERT INTO users (user_id, guild_id, notify_channel_id, notify_dms, catchup_enabled, is_whitelisted, created_at, updated_at) VALUES (?, ?, NULL, 0, 0, 0, ?, ?) """, (user_id, guild_id, now, now), )
def get_user_settings(self, user_id: int) -> UserSettings | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), next_playlist_run=float(row["next_playlist_run"]) if row["next_playlist_run"] else 0.0, next_latest_run=float(row["next_latest_run"]) if row["next_latest_run"] else 0.0, priority_job=row["priority_job"], created_at=row["created_at"], updated_at=row["updated_at"], )
def set_notify_target(self, user_id: int, guild_id: int | None, channel_id: int | None, dms: bool) -> None: self.ensure_user(user_id, guild_id) now = utc_now() with self.cursor() as cursor: cursor.execute( """ UPDATE users SET guild_id=?, notify_channel_id=?, notify_dms=?, updated_at=? WHERE user_id=? """, (guild_id, channel_id, int(dms), now, user_id), )
def set_catchup(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET catchup_enabled=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def set_whitelisted(self, user_id: int, enabled: bool) -> None: self.ensure_user(user_id) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE users SET is_whitelisted=?, updated_at=? WHERE user_id=?", (int(enabled), now, user_id), )
def is_whitelisted(self, user_id: int) -> bool: with self.cursor() as cursor: cursor.execute("SELECT is_whitelisted FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone() return bool(row[0]) if row else False
def list_whitelisted_users(self) -> list[int]: with self.cursor() as cursor: cursor.execute("SELECT user_id FROM users WHERE is_whitelisted=1 ORDER BY user_id") rows = cursor.fetchall() return [row[0] for row in rows]
def set_worker_schedule(self, user_id: int, *, next_playlist_run: float | None = None, next_latest_run: float | None = None, priority_job: str | None = None) -> None: """Update worker scheduling state. Only updates provided fields.""" self.ensure_user(user_id) now = utc_now()
updates = [] params = []
if next_playlist_run is not None: updates.append("next_playlist_run=?") params.append(next_playlist_run) if next_latest_run is not None: updates.append("next_latest_run=?") params.append(next_latest_run) if priority_job is not None: updates.append("priority_job=?") params.append(priority_job)
if updates: updates.append("updated_at=?") params.append(now) params.append(user_id)
query = f"UPDATE users SET {', '.join(updates)} WHERE user_id=?" with self.cursor() as cursor: cursor.execute(query, params)
def get_worker_schedule(self, user_id: int) -> tuple[float, float, str | None]: """Get worker scheduling state. Returns (next_playlist_run, next_latest_run, priority_job).""" with self.cursor() as cursor: cursor.execute("SELECT next_playlist_run, next_latest_run, priority_job FROM users WHERE user_id=?", (user_id,)) row = cursor.fetchone()
if row is None: return 0.0, 0.0, None
return ( float(row["next_playlist_run"]) if row["next_playlist_run"] else 0.0, float(row["next_latest_run"]) if row["next_latest_run"] else 0.0, row["priority_job"] )
def delete_user(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM channel_trackers WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM channels WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM playlists WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,)) cursor.execute("DELETE FROM users WHERE user_id=?", (user_id,))
def get_channel(self, user_id: int, channel_id: str) -> ChannelRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id)) row = cursor.fetchone() return self._row_to_channel(user_id, row) if row else None
def count_channels(self, user_id: int | None = None, filter_name: str | None = "all") -> int: query = "SELECT COUNT(*) FROM channels c" conditions: list[str] = [] params: list[object] = []
if user_id is not None: conditions.append("c.user_id=?") params.append(user_id)
match filter_name: case "blacklisted": conditions.append("c.blacklisted=1") case "manual": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
if conditions: query += " WHERE " + " AND ".join(conditions)
with self.cursor() as cursor: cursor.execute(query, params) row = cursor.fetchone()
return int(row[0] if row else 0)
def list_channels(self, user_id: int, filter_name: str = "all") -> Iterator[ChannelRecord]: query = "SELECT c.* FROM channels c" conditions: list[str] = ["c.user_id = ?"] params: list[object] = [user_id]
match filter_name: case "blacklisted": conditions.append("c.blacklisted = 1") case "manual": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted = 0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
query += " WHERE " + " AND ".join(conditions) query += " ORDER BY c.title COLLATE NOCASE, c.channel_id"
with self.cursor() as cursor: cursor.execute(query, params) rows = cursor.fetchall()
for row in rows: yield self._row_to_channel(user_id, row)
def list_channels_paginated(self, user_id: int, limit: int = 5, offset: int = 0, filter_name: str = "all") -> list[ChannelRecord]: query = "SELECT c.* FROM channels c" conditions: list[str] = ["c.user_id=?"] params: list[object] = [user_id]
match filter_name: case "blacklisted": conditions.append("c.blacklisted=1") case "manual": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user')") case "playlist": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user')") case "tracked": conditions.append("c.blacklisted=0") conditions.append("EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id)") case _: pass
query += " WHERE " + " AND ".join(conditions) query += " ORDER BY c.title COLLATE NOCASE, c.channel_id LIMIT ? OFFSET ?"
params.extend([limit, offset])
with self.cursor() as cursor: cursor.execute(query, params) rows = cursor.fetchall()
return [self._row_to_channel(user_id, row) for row in rows]
def upsert_channel( self, user_id: int, channel_id: str, title: str, *, blacklisted: bool | None = None, last_seen_ts: str | None = None, trackers: Sequence[str] | None = None, ) -> ChannelRecord: now = utc_now() existing = self.get_channel(user_id, channel_id)
resolved_blacklisted = existing.blacklisted if existing and blacklisted is None else bool(blacklisted) if blacklisted is not None else False resolved_last_seen = last_seen_ts if last_seen_ts is not None else (existing.last_seen_ts if existing else None)
with self.cursor() as cursor: cursor.execute( """ INSERT INTO channels (user_id, channel_id, title, blacklisted, last_seen_ts, created_at, updated_at) VALUES (?, ?, ?, ?, ?, COALESCE(?, ?), ?) ON CONFLICT(user_id, channel_id) DO UPDATE SET title=excluded.title, blacklisted=excluded.blacklisted, last_seen_ts=CASE WHEN excluded.last_seen_ts IS NULL THEN channels.last_seen_ts WHEN channels.last_seen_ts IS NULL THEN excluded.last_seen_ts WHEN excluded.last_seen_ts > channels.last_seen_ts THEN excluded.last_seen_ts ELSE channels.last_seen_ts END, updated_at=excluded.updated_at """, ( user_id, channel_id, title, int(resolved_blacklisted), resolved_last_seen, existing.created_at if existing else now, now, now ), )
if trackers: incoming_trackers = list(dict.fromkeys([t for t in trackers if t])) cursor.executemany( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) VALUES (?, ?, ?, ?) """, [(user_id, channel_id, tracker_id, now) for tracker_id in incoming_trackers] )
return self.get_channel(user_id, channel_id) or ChannelRecord(user_id=user_id, channel_id=channel_id, title=title)
def upsert_playlist_channels( self, user_id: int, playlist_id: str, channels: dict[str, str], last_seen: dict[str, str] | None = None ) -> None: now = utc_now() is_dict_present = last_seen is not None last_seen_dict = last_seen or {}
with self.cursor() as cursor: cursor.executemany( """ INSERT INTO channels ( user_id, channel_id, title, blacklisted, last_seen_ts, created_at, updated_at ) -- FIX: If it's a new row insert and incoming is NULL, default to :now VALUES (:user_id, :channel_id, :title, 0, COALESCE(:incoming_last_seen, :now), :now, :now) ON CONFLICT(user_id, channel_id) DO UPDATE SET title = excluded.title, created_at = CASE WHEN excluded.title != channels.title THEN max(excluded.created_at, channels.created_at) ELSE channels.created_at END,
last_seen_ts = CASE -- RULE 1: last_seen dict is null WHEN :is_dict_present = 0 THEN COALESCE(channels.last_seen_ts, excluded.updated_at)
-- RULE 2: last_seen dict is present ELSE CASE WHEN channels.last_seen_ts IS NULL OR excluded.last_seen_ts > channels.last_seen_ts THEN excluded.last_seen_ts ELSE channels.last_seen_ts END END,
updated_at = excluded.updated_at """, [ { "user_id": user_id, "channel_id": cid, "title": title, "incoming_last_seen": last_seen_dict.get(cid), "is_dict_present": 1 if is_dict_present else 0, "now": now, } for cid, title in channels.items() ], )
cursor.executemany( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) VALUES (?, ?, ?, ?) """, [(user_id, cid, playlist_id, now) for cid in channels], )
def set_channel_blacklisted(self, user_id: int, channel_id: str, title: str, blacklisted: bool) -> ChannelRecord: record = self.upsert_channel(user_id, channel_id, title, blacklisted=blacklisted) now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET blacklisted=?, updated_at=? WHERE user_id=? AND channel_id=?", (int(blacklisted), now, user_id, channel_id), ) return self.get_channel(user_id, channel_id) or record
def remove_channel(self, user_id: int, channel_id: str) -> None: with self.cursor() as cursor: cursor.execute( "DELETE FROM channel_trackers WHERE user_id=? AND channel_id=?", (user_id, channel_id) ) cursor.execute( "DELETE FROM channels WHERE user_id=? AND channel_id=?", (user_id, channel_id) )
def add_channel_tracker(self, user_id: int, channel_id: str, tracker: str): now = utc_now()
with self.cursor() as cursor: cursor.execute( """ INSERT OR IGNORE INTO channel_trackers (user_id, channel_id, tracker_id, created_at) SELECT ?, ?, ?, ? WHERE EXISTS ( SELECT 1 FROM channels WHERE user_id=? AND channel_id=? ) """, (user_id, channel_id, tracker, now, user_id, channel_id), )
def remove_channel_tracker(self, user_id: int, channel_id: str, tracker: str) -> bool: with self.cursor() as cursor: cursor.execute( """ DELETE FROM channel_trackers WHERE user_id=? AND channel_id=? AND tracker_id=? """, (user_id, channel_id, tracker), )
removed = cursor.rowcount > 0
if not removed: return False
cursor.execute( """ DELETE FROM channels WHERE user_id=? AND channel_id=? AND blacklisted=0 AND NOT EXISTS ( SELECT 1 FROM channel_trackers WHERE user_id=? AND channel_id=? ) """, (user_id, channel_id, user_id, channel_id), )
return True
def remove_orphaned_playlist_channels(self, user_id: int, playlist_id: str, cutoff: str) -> None: with self.cursor() as cursor: cursor.execute(""" CREATE TEMP TABLE tmp_stale AS SELECT c.channel_id FROM channels c JOIN channel_trackers ct ON ct.user_id = c.user_id AND ct.channel_id = c.channel_id WHERE c.user_id = ? AND ct.tracker_id = ? AND c.updated_at < ? """, (user_id, playlist_id, cutoff))
cursor.execute(""" DELETE FROM channel_trackers WHERE user_id = ? AND tracker_id = ? AND channel_id IN (SELECT channel_id FROM tmp_stale) """, (user_id, playlist_id))
cursor.execute(""" DELETE FROM channels WHERE user_id = ? AND channel_id IN ( SELECT s.channel_id FROM tmp_stale s LEFT JOIN channel_trackers ct ON ct.user_id = ? AND ct.channel_id = s.channel_id WHERE ct.channel_id IS NULL ) AND blacklisted = 0 """, (user_id, user_id))
cursor.execute("DROP TABLE tmp_stale")
def reset_channels_last_seen(self, user_id: int) -> int: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE channels SET last_seen_ts=NULL, updated_at=? WHERE user_id=?", (now, user_id), ) return cursor.rowcount
@staticmethod def _row_to_playlist(row: sqlite3.Row) -> PlaylistRecord: return PlaylistRecord( user_id=row["user_id"], playlist_id=row["playlist_id"], title=row["title"], is_private=bool(row["is_private"]), last_synced_ts=row["last_synced_ts"], created_at=row["created_at"], updated_at=row["updated_at"], )
def _row_to_channel(self, user_id: int, row: sqlite3.Row) -> ChannelRecord: with self.cursor() as cursor: cursor.execute( """ SELECT tracker_id FROM channel_trackers WHERE user_id=? AND channel_id=? """, (user_id, row["channel_id"]), ) trackers = [r[0] for r in cursor.fetchall()]
return ChannelRecord( user_id=user_id, channel_id=row["channel_id"], title=row["title"], blacklisted=bool(row["blacklisted"]), last_seen_ts=row["last_seen_ts"], trackers=trackers, created_at=row["created_at"], updated_at=row["updated_at"], )
def upsert_playlist(self, user_id: int, playlist_id: str, title: str, *, is_private: bool = False) -> PlaylistRecord: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO playlists (user_id, playlist_id, title, is_private, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, playlist_id) DO UPDATE SET title=excluded.title, is_private=excluded.is_private, updated_at=excluded.updated_at """, (user_id, playlist_id, title, int(is_private), now, now), ) return self.get_playlist(user_id, playlist_id)
def get_playlist(self, user_id: int, playlist_id: str) -> PlaylistRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM playlists WHERE user_id=? AND playlist_id=?", (user_id, playlist_id)) row = cursor.fetchone() if row is None: return None return self._row_to_playlist(row)
def list_playlists(self, user_id: int) -> Iterator[PlaylistRecord]: with self.cursor() as cursor: cursor.execute( """ SELECT * FROM playlists WHERE user_id=? ORDER BY title COLLATE NOCASE, playlist_id """, (user_id,), )
while True: rows = cursor.fetchmany(10) if not rows: break
for row in rows: if row: yield self._row_to_playlist(row)
def count_playlists(self, user_id: int) -> int: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM playlists WHERE user_id=?", (user_id,)) row = cursor.fetchone() return int(row[0] if row else 0)
def list_playlists_paginated(self, user_id: int, limit: int = 10, offset: int = 0) -> list[PlaylistRecord]: with self.cursor() as cursor: cursor.execute( "SELECT * FROM playlists WHERE user_id=? ORDER BY title COLLATE NOCASE, playlist_id LIMIT ? OFFSET ?", (user_id, limit, offset), ) rows = cursor.fetchall() return [self.get_playlist(user_id, row["playlist_id"]) for row in rows if row]
def set_playlist_synced(self, user_id: int, playlist_id: str, ts: str | None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( "UPDATE playlists SET last_synced_ts=?, updated_at=? WHERE user_id=? AND playlist_id=?", (ts, now, user_id, playlist_id), )
def remove_playlist(self, user_id: int, playlist_id: str) -> int: with self.cursor() as cursor: cursor.execute( """ DELETE FROM channel_trackers WHERE user_id = ? AND tracker_id = ? """, (user_id, playlist_id), ) removed_count = cursor.rowcount
cursor.execute( """ DELETE FROM playlists WHERE user_id = ? AND playlist_id = ? """, (user_id, playlist_id), )
cursor.execute( """ DELETE FROM channels WHERE user_id = ? AND blacklisted = 0 AND channel_id NOT IN ( SELECT channel_id FROM channel_trackers WHERE user_id = ? ) """, (user_id, user_id), )
return removed_count
def list_users(self) -> list[UserSettings]: with self.cursor() as cursor: cursor.execute("SELECT * FROM users ORDER BY user_id") rows = cursor.fetchall() return [ UserSettings( user_id=row["user_id"], guild_id=row["guild_id"], notify_channel_id=row["notify_channel_id"], notify_dms=bool(row["notify_dms"]), catchup_enabled=bool(row["catchup_enabled"]), created_at=row["created_at"], updated_at=row["updated_at"], ) for row in rows ]
def count_users(self) -> int: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") row = cursor.fetchone() return int(row[0] if row else 0)
def set_auth_record(self, user_id: int, credential_json: str, email: str | None = None) -> None: now = utc_now() with self.cursor() as cursor: cursor.execute( """ INSERT INTO auth_records (user_id, credential_json, email, created_at, updated_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET credential_json=excluded.credential_json, email=excluded.email, updated_at=excluded.updated_at """, (user_id, credential_json, email, now, now), )
def get_auth_record(self, user_id: int) -> AuthRecord | None: with self.cursor() as cursor: cursor.execute("SELECT * FROM auth_records WHERE user_id=?", (user_id,)) row = cursor.fetchone() if row is None: return None return AuthRecord( user_id=row["user_id"], credential_json=row["credential_json"], email=row["email"], created_at=row["created_at"], updated_at=row["updated_at"], )
def remove_auth_record(self, user_id: int) -> None: with self.cursor() as cursor: cursor.execute("DELETE FROM auth_records WHERE user_id=?", (user_id,))
def stats_snapshot(self) -> StatsSnapshot: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM users") users = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels") channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists") playlists = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM channels WHERE blacklisted=1") blacklisted = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(DISTINCT channel_id) FROM channel_trackers WHERE tracker_id='user'") pinned = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM users WHERE notify_dms=1") dms = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM users WHERE notify_channel_id IS NOT NULL") channel_notifs = int(cursor.fetchone()[0]) cursor.execute(""" SELECT COUNT(*) FROM channels c WHERE c.blacklisted=0 AND EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id = 'user') """) manual_channels = int(cursor.fetchone()[0]) cursor.execute(""" SELECT COUNT(*) FROM channels c WHERE c.blacklisted=0 AND EXISTS (SELECT 1 FROM channel_trackers ct WHERE ct.user_id = c.user_id AND ct.channel_id = c.channel_id AND ct.tracker_id != 'user') """) playlist_channels = int(cursor.fetchone()[0]) avg_channels = channels / users if users else 0.0 avg_playlists = playlists / users if users else 0.0 return StatsSnapshot( users=users, channels=channels, playlists=playlists, manual_channels=manual_channels, playlist_channels=playlist_channels, blacklisted_channels=blacklisted, avg_channels_per_user=avg_channels, avg_playlists_per_user=avg_playlists, pinned_channels=pinned, dm_notifications=dms, channel_notifications=channel_notifs )
def count_user_objects(self, user_id: int) -> tuple[int, int]: with self.cursor() as cursor: cursor.execute("SELECT COUNT(*) FROM channels WHERE user_id=?", (user_id,)) channels = int(cursor.fetchone()[0]) cursor.execute("SELECT COUNT(*) FROM playlists WHERE user_id=?", (user_id,)) playlists = int(cursor.fetchone()[0]) return channels, playlists

from __future__ import annotations

import json
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

import aiohttp
from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials

from models import VideoRecord

YOUTUBE_CHANNEL_FEED = "https://www.youtube.com/feeds/videos.xml?channel_id={channel_id}"
YOUTUBE_PLAYLIST_FEED = "https://www.youtube.com/feeds/videos.xml?playlist_id={playlist_id}"
YOUTUBE_API_SEARCH = "https://www.googleapis.com/youtube/v3/search"
YOUTUBE_API_PLAYLISTS = "https://www.googleapis.com/youtube/v3/playlists"
YOUTUBE_API_PLAYLIST_ITEMS = "https://www.googleapis.com/youtube/v3/playlistItems"

NS = {
    "atom": "http://www.w3.org/2005/Atom",
    "yt": "http://www.youtube.com/xml/schemas/2015",
    "media": "http://search.yahoo.com/mrss/",
}


@dataclass(slots=True)
class FeedResult:
    title: str
    videos: list[VideoRecord]


@dataclass(slots=True)
class PlaylistAccess:
    can_access: bool
    source: str
    title: str | None = None


class YouTubeService:
    def __init__(self, bot):
        self.bot = bot

    @staticmethod
    def _is_at_or_newer(left: str, right: str) -> bool:
        try:
            return datetime.fromisoformat(left) >= datetime.fromisoformat(right)
        except ValueError:
            return left >= right

    def _make_credentials(self, record) -> Any:
        if not record:
            return None
        creds = Credentials.from_authorized_user_info(json.loads(record.credential_json))
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        return creds

    def _api_key(self) -> str | None:
        key = getattr(self.bot.config, "youtube_api_key", None)
        return key or None

    def _auth_headers(self, user_id: int | None = None) -> tuple[dict[str, str], str]:
        if user_id is not None:
            record = self.bot.db.get_auth_record(user_id)
            creds = self._make_credentials(record)
            if creds:
                if creds.expired and creds.refresh_token:
                    creds.refresh(Request())
                return {"Authorization": f"Bearer {creds.token}"}, "user-auth"
        api_key = self._api_key()
        if api_key:
            return {}, "api-key"
        return {}, "none"

    async def fetch_channel_feed(self, session: aiohttp.ClientSession, channel_id: str) -> FeedResult | None:
        url = YOUTUBE_CHANNEL_FEED.format(channel_id=channel_id)
        return await self._fetch_feed(session, url, identifier=channel_id)

    async def fetch_playlist_feed(self, session: aiohttp.ClientSession, playlist_id: str) -> FeedResult | None:
        url = YOUTUBE_PLAYLIST_FEED.format(playlist_id=playlist_id)
        result = await self._fetch_feed(session, url, identifier=playlist_id)
        if result and result.videos:
            return result
        return result

    async def fetch_playlist_items_for_user(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> FeedResult | None:
        headers, source = self._auth_headers(user_id)
        if source == "none":
            return None
        params = {
            "part": "snippet",
            "playlistId": playlist_id,
            "maxResults": 50,
        }
        api_key = self._api_key()
        if source == "api-key" and api_key:
            params["key"] = api_key
        videos: list[VideoRecord] = []
        playlist_title = playlist_id
        next_token: str | None = None
        while True:
            if next_token:
                params["pageToken"] = next_token
            async with session.get(YOUTUBE_API_PLAYLIST_ITEMS, params=params, headers=headers, proxy=self.bot.config.proxy) as response:
                if response.status != 200:
                    return None
                data = await response.json()
            for item in data.get("items", []):
                snippet = item.get("snippet", {})
                resource = snippet.get("resourceId", {})
                video_id = resource.get("videoId")
                if not video_id:
                    continue
                channel_id = snippet.get("channelId") or snippet.get("videoOwnerChannelId") or "unknown"
                channel_title = snippet.get("videoOwnerChannelTitle") or snippet.get("channelTitle") or "Unknown"
                published = snippet.get("publishedAt") or self._utc_now()
                videos.append(
                    VideoRecord(
                        video_id=video_id,
                        title=snippet.get("title") or "Untitled",
                        url=f"https://www.youtube.com/watch?v={video_id}",
                        channel_id=channel_id,
                        channel_title=channel_title,
                        published_at=published,
                        thumbnail_url=self._thumbnail_url(video_id),
                    )
                )
            if not playlist_title and data.get("items"):
                playlist_title = data["items"][0].get("snippet", {}).get("playlistTitle", playlist_id)
            next_token = data.get("nextPageToken")
            if not next_token:
                break
        return FeedResult(title=playlist_title, videos=videos)

    async def check_playlist_access(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> PlaylistAccess:
        headers, source = self._auth_headers(user_id)
        params = {"part": "snippet", "id": playlist_id, "maxResults": 1}
        if source == "api-key":
            params["key"] = self._api_key()
        async with session.get(YOUTUBE_API_PLAYLISTS, params=params, headers=headers, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return PlaylistAccess(False, source)
            data = await response.json()
        items = data.get("items", [])
        if not items:
            return PlaylistAccess(False, source)
        snippet = items[0].get("snippet", {})
        title = snippet.get("title") or playlist_id
        return PlaylistAccess(True, source, title=title)

    async def fetch_private_playlist_items(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> FeedResult | None:
        return await self.fetch_playlist_items_for_user(session, user_id, playlist_id)

    async def fetch_recent_channel_videos(self, session: aiohttp.ClientSession, channel_id: str, *, use_api: bool = False) -> FeedResult | None:
        if use_api:
            return await self._fetch_api_channel_videos(session, channel_id)
        return await self.fetch_channel_feed(session, channel_id)

    async def fetch_latest_channel_videos(
        self,
        session: aiohttp.ClientSession,
        channel_id: str,
        *,
        last_seen: str | None = None,
    ) -> FeedResult | None:
        rss_result = await self.fetch_channel_feed(session, channel_id)
        if rss_result is None:
            return await self._fetch_api_channel_videos(session, channel_id)
        if last_seen is None:
            return rss_result
        if not rss_result.videos:
            return await self._fetch_api_channel_videos(session, channel_id)
        if all(self._is_at_or_newer(video.published_at, last_seen) for video in rss_result.videos):
            api_result = await self._fetch_api_channel_videos(session, channel_id)
            return api_result or rss_result
        return rss_result

    async def _fetch_api_channel_videos(self, session: aiohttp.ClientSession, channel_id: str) -> FeedResult | None:
        api_key = self._api_key()
        params = {
            "part": "snippet",
            "channelId": channel_id,
            "type": "video",
            "order": "date",
            "maxResults": 50,
        }
        if api_key:
            params["key"] = api_key
        async with session.get(YOUTUBE_API_SEARCH, params=params, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return None
            data = await response.json()
        videos: list[VideoRecord] = []
        channel_title = channel_id
        for item in data.get("items", []):
            snippet = item.get("snippet", {})
            video_id = item.get("id", {}).get("videoId")
            if not video_id:
                continue
            channel_title = snippet.get("channelTitle") or channel_title
            published = snippet.get("publishedAt") or self._utc_now()
            videos.append(
                VideoRecord(
                    video_id=video_id,
                    title=snippet.get("title") or "Untitled",
                    url=f"https://www.youtube.com/watch?v={video_id}",
                    channel_id=channel_id,
                    channel_title=channel_title,
                    published_at=published,
                    thumbnail_url=self._thumbnail_url(video_id),
                )
            )
        return FeedResult(title=channel_title, videos=videos)

    async def _fetch_feed(self, session: aiohttp.ClientSession, url: str, *, identifier: str) -> FeedResult | None:
        async with session.get(url, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return None
            xml = await response.text()
        try:
            root = ET.fromstring(xml)
        except ET.ParseError:
            return None
        title = root.findtext("atom:title", default=identifier, namespaces=NS) or identifier
        videos: list[VideoRecord] = []
        for entry in root.findall("atom:entry", NS):
            video_id = entry.findtext("yt:videoId", default="", namespaces=NS)
            if not video_id:
                continue
            channel_id = entry.findtext("yt:channelId", default=identifier, namespaces=NS) or identifier
            channel_title = entry.findtext("atom:author/atom:name", default=title, namespaces=NS) or title
            published = entry.findtext("atom:published", default=self._utc_now(), namespaces=NS) or self._utc_now()
            link = entry.find("atom:link", NS)
            videos.append(
                VideoRecord(
                    video_id=video_id,
                    title=entry.findtext("atom:title", default="Untitled", namespaces=NS) or "Untitled",
                    url=link.attrib.get("href") if link is not None else f"https://www.youtube.com/watch?v={video_id}",
                    channel_id=channel_id,
                    channel_title=channel_title,
                    published_at=published,
                    thumbnail_url=self._thumbnail_url(video_id),
                )
            )
        return FeedResult(title=title, videos=videos)

    def _thumbnail_url(self, video_id: str) -> str:
        return f"https://img.youtube.com/vi/{video_id}/maxresdefault.jpg"

    def _utc_now(self) -> str:
        return datetime.now(timezone.utc).isoformat()

from __future__ import annotations

import json
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

import aiohttp
from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials

from models import VideoRecord

YOUTUBE_CHANNEL_FEED = "https://www.youtube.com/feeds/videos.xml?channel_id={channel_id}"
YOUTUBE_PLAYLIST_FEED = "https://www.youtube.com/feeds/videos.xml?playlist_id={playlist_id}"
YOUTUBE_API_SEARCH = "https://www.googleapis.com/youtube/v3/search"
YOUTUBE_API_PLAYLISTS = "https://www.googleapis.com/youtube/v3/playlists"
YOUTUBE_API_PLAYLIST_ITEMS = "https://www.googleapis.com/youtube/v3/playlistItems"

NS = {
    "atom": "http://www.w3.org/2005/Atom",
    "yt": "http://www.youtube.com/xml/schemas/2015",
    "media": "http://search.yahoo.com/mrss/",
}


@dataclass(slots=True)
class FeedResult:
    title: str
    videos: list[VideoRecord]


@dataclass(slots=True)
class PlaylistAccess:
    can_access: bool
    source: str
    title: str | None = None


class YouTubeService:
    def __init__(self, bot):
        self.bot = bot

    @staticmethod
    def _is_at_or_newer(left: str, right: str) -> bool:
        try:
            return datetime.fromisoformat(left) >= datetime.fromisoformat(right)
        except ValueError:
            return left >= right

    def _make_credentials(self, record) -> Any:
        if not record:
            return None
        creds = Credentials.from_authorized_user_info(json.loads(record.credential_json))
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        return creds

    def _api_key(self) -> str | None:
        key = getattr(self.bot.config, "youtube_api_key", None)
        return key or None

    def _auth_headers(self, user_id: int | None = None) -> tuple[dict[str, str], str]:
        if user_id is not None:
            record = self.bot.db.get_auth_record(user_id)
            creds = self._make_credentials(record)
            if creds:
                if creds.expired and creds.refresh_token:
                    creds.refresh(Request())
                return {"Authorization": f"Bearer {creds.token}"}, "user-auth"
        api_key = self._api_key()
        if api_key:
            return {}, "api-key"
        return {}, "none"

    async def fetch_channel_feed(self, session: aiohttp.ClientSession, channel_id: str) -> FeedResult | None:
        url = YOUTUBE_CHANNEL_FEED.format(channel_id=channel_id)
        return await self._fetch_feed(session, url, identifier=channel_id)

    async def fetch_playlist_feed(self, session: aiohttp.ClientSession, playlist_id: str) -> FeedResult | None:
        url = YOUTUBE_PLAYLIST_FEED.format(playlist_id=playlist_id)
        result = await self._fetch_feed(session, url, identifier=playlist_id)
        if result and result.videos:
            return result
        return result

    async def fetch_playlist_items_for_user(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> FeedResult | None:
        headers, source = self._auth_headers(user_id)
        if source == "none":
            return None
        params = {
            "part": "snippet,contentDetails",
            "playlistId": playlist_id,
            "maxResults": 200,
        }
        api_key = self._api_key()
        if source == "api-key" and api_key:
            params["key"] = api_key
        videos: list[VideoRecord] = []
        next_token: str | None = None
        while True:
            if next_token:
                params["pageToken"] = next_token
            async with session.get(YOUTUBE_API_PLAYLIST_ITEMS, params=params, headers=headers, proxy=self.bot.config.proxy) as response:
                if response.status != 200:
                    return None
                data = await response.json()
            for item in data.get("items", []):
                snippet = item.get("snippet", {})
                resource = snippet.get("resourceId", {})
                video_id = resource.get("videoId")
                if not video_id:
                    continue
                channel_id = snippet.get("channelId") or snippet.get("videoOwnerChannelId") or "unknown"
                channel_title = snippet.get("videoOwnerChannelTitle") or snippet.get("channelTitle") or "Unknown"
                published = snippet.get("publishedAt") or self._utc_now()
                videos.append(
                    VideoRecord(
                        video_id=video_id,
                        title=snippet.get("title") or "Untitled",
                        url=f"https://www.youtube.com/watch?v={video_id}",
                        channel_id=channel_id,
                        channel_title=channel_title,
                        published_at=published,
                        thumbnail_url=self._thumbnail_url(video_id),
                    )
                )
            next_token = data.get("nextPageToken")
            if not next_token:
                break
        playlist_title = playlist_id
        return FeedResult(title=playlist_title, videos=videos)

    async def check_playlist_access(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> PlaylistAccess:
        headers, source = self._auth_headers(user_id)
        params = {"part": "snippet", "id": playlist_id, "maxResults": 1}
        if source == "api-key":
            params["key"] = self._api_key()
        async with session.get(YOUTUBE_API_PLAYLISTS, params=params, headers=headers, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return PlaylistAccess(False, source)
            data = await response.json()
        items = data.get("items", [])
        if not items:
            return PlaylistAccess(False, source)
        snippet = items[0].get("snippet", {})
        title = snippet.get("title") or playlist_id
        return PlaylistAccess(True, source, title=title)

    async def fetch_private_playlist_items(self, session: aiohttp.ClientSession, user_id: int, playlist_id: str) -> FeedResult | None:
        return await self.fetch_playlist_items_for_user(session, user_id, playlist_id)

    async def fetch_recent_channel_videos(self, session: aiohttp.ClientSession, channel_id: str, *, use_api: bool = False) -> FeedResult | None:
        if use_api:
            return await self._fetch_api_channel_videos(session, channel_id)
        return await self.fetch_channel_feed(session, channel_id)

    async def fetch_latest_channel_videos(
        self,
        session: aiohttp.ClientSession,
        channel_id: str,
        *,
        last_seen: str | None = None,
    ) -> FeedResult | None:
        rss_result = await self.fetch_channel_feed(session, channel_id)
        if rss_result is None:
            return await self._fetch_api_channel_videos(session, channel_id)
        if last_seen is None:
            return rss_result
        if not rss_result.videos:
            return await self._fetch_api_channel_videos(session, channel_id)
        if all(self._is_at_or_newer(video.published_at, last_seen) for video in rss_result.videos):
            api_result = await self._fetch_api_channel_videos(session, channel_id)
            return api_result or rss_result
        return rss_result

    async def _fetch_api_channel_videos(self, session: aiohttp.ClientSession, channel_id: str) -> FeedResult | None:
        api_key = self._api_key()
        params = {
            "part": "snippet",
            "channelId": channel_id,
            "type": "video",
            "order": "date",
            "maxResults": 50,
        }
        if api_key:
            params["key"] = api_key
        async with session.get(YOUTUBE_API_SEARCH, params=params, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return None
            data = await response.json()
        videos: list[VideoRecord] = []
        channel_title = channel_id
        for item in data.get("items", []):
            snippet = item.get("snippet", {})
            video_id = item.get("id", {}).get("videoId")
            if not video_id:
                continue
            channel_title = snippet.get("channelTitle") or channel_title
            published = snippet.get("publishedAt") or self._utc_now()
            videos.append(
                VideoRecord(
                    video_id=video_id,
                    title=snippet.get("title") or "Untitled",
                    url=f"https://www.youtube.com/watch?v={video_id}",
                    channel_id=channel_id,
                    channel_title=channel_title,
                    published_at=published,
                    thumbnail_url=self._thumbnail_url(video_id),
                )
            )
        return FeedResult(title=channel_title, videos=videos)

    async def _fetch_feed(self, session: aiohttp.ClientSession, url: str, *, identifier: str) -> FeedResult | None:
        async with session.get(url, proxy=self.bot.config.proxy) as response:
            if response.status != 200:
                return None
            xml = await response.text()
        try:
            root = ET.fromstring(xml)
        except ET.ParseError:
            return None
        title = root.findtext("atom:title", default=identifier, namespaces=NS) or identifier
        videos: list[VideoRecord] = []
        for entry in root.findall("atom:entry", NS):
            video_id = entry.findtext("yt:videoId", default="", namespaces=NS)
            if not video_id:
                continue
            channel_id = entry.findtext("yt:channelId", default=identifier, namespaces=NS) or identifier
            channel_title = entry.findtext("atom:author/atom:name", default=title, namespaces=NS) or title
            published = entry.findtext("atom:published", default=self._utc_now(), namespaces=NS) or self._utc_now()
            link = entry.find("atom:link", NS)
            videos.append(
                VideoRecord(
                    video_id=video_id,
                    title=entry.findtext("atom:title", default="Untitled", namespaces=NS) or "Untitled",
                    url=link.attrib.get("href") if link is not None else f"https://www.youtube.com/watch?v={video_id}",
                    channel_id=channel_id,
                    channel_title=channel_title,
                    published_at=published,
                    thumbnail_url=self._thumbnail_url(video_id),
                )
            )
        return FeedResult(title=title, videos=videos)

    def _thumbnail_url(self, video_id: str) -> str:
        return f"https://img.youtube.com/vi/{video_id}/maxresdefault.jpg"

    def _utc_now(self) -> str:
        return datetime.now(timezone.utc).isoformat()
